package com.myassist.assistant.network;
import com.myassist.assistant.BuildConfig; import com.myassist.assistant.session.SessionManager; import java.util.concurrent.TimeUnit; import okhttp3.OkHttpClient; import okhttp3.Request;
public final class ApiClient { public static final String BASE_URL=BuildConfig.API_BASE_URL+"/"; private static OkHttpClient client; private static SessionManager session; public static void init(SessionManager s){session=s;client=new OkHttpClient.Builder().connectTimeout(15,TimeUnit.SECONDS).readTimeout(20,TimeUnit.SECONDS).addInterceptor(c->{Request r=c.request();Request.Builder b=r.newBuilder();String t=session==null?null:session.token();if(t!=null)b.header("Authorization","Bearer "+t);return c.proceed(b.build());}).build();} public static OkHttpClient http(){return client;} public static class ApiException extends Exception{public final int code;public final String userMessage;public ApiException(int c,String m){super(m);code=c;userMessage=m;}} }